#!/usr/bin/env bash

REF=<REFERENCE_GENOME.fasta>
BAM=<DUPLICATE_PROCESSED.bam>
OUT=<OUTPUT_PREFIX>

# MethylDackel v0.6.1

MethylDackel extract \
    --fraction \
    --CHG \
    --CHH \
    -o "${OUT}" \
    "${REF}" \
    "${BAM}"

